intermediario.solucao:
WITH freq AS (
    SELECT produto_id, COUNT(*) AS n FROM fato_vendas GROUP BY produto_id
)
SELECT MAX(n) AS maior, percentile_approx(n, 0.5) AS mediana,
       MAX(n) / percentile_approx(n, 0.5) AS razao
FROM freq;
